<?php get_header();?><main id="content"><section class="rp-hero"><div class="rp-container rp-hero__inner"><div><p class="rp-eyebrow"><?php echo esc_html(get_theme_mod('rss_prism_hero_eyebrow','A CLEARER WAY FORWARD'));?></p><h1><?php echo esc_html(get_theme_mod('rss_prism_hero_title','Build something remarkable.'));?></h1><p class="rp-hero__text"><?php echo esc_html(get_theme_mod('rss_prism_hero_text','A flexible starting point for your business, portfolio, publication, or personal website.'));?></p><div class="rp-hero__actions"><?php $l=get_theme_mod('rss_prism_hero_primary_label','Explore our work');$u=get_theme_mod('rss_prism_hero_primary_url','#latest');if($l&&$u):?><a class="rp-button" href="<?php echo esc_url($u);?>"><?php echo esc_html($l);?> →</a><?php endif;$l=get_theme_mod('rss_prism_hero_secondary_label','Learn more');$u=get_theme_mod('rss_prism_hero_secondary_url','#about');if($l&&$u):?><a class="rp-button rp-button--outline" href="<?php echo esc_url($u);?>"><?php echo esc_html($l);?></a><?php endif;?></div></div><div class="rp-hero__visual" aria-hidden="true"><div class="rp-hero__orb"></div></div></div></section><section class="rp-section rp-container" id="about"><h2><?php echo esc_html(get_theme_mod('rss_prism_features_title','Everything you need to begin'));?></h2><p><?php echo esc_html(get_theme_mod('rss_prism_features_text','Flexible building blocks to make the site your own.'));?></p><div class="rp-card-grid"><article class="rp-card"><div class="rp-card__icon">✦</div><h3><?php esc_html_e('Make it yours','rss-prism');?></h3><p><?php esc_html_e('Customize colours, widths, corners, header, and footer.','rss-prism');?></p></article><article class="rp-card"><div class="rp-card__icon">▤</div><h3><?php esc_html_e('Flexible layouts','rss-prism');?></h3><p><?php esc_html_e('Present articles in a card grid or horizontal list.','rss-prism');?></p></article><article class="rp-card"><div class="rp-card__icon">⌁</div><h3><?php esc_html_e('Responsive by design','rss-prism');?></h3><p><?php esc_html_e('Mobile navigation and keyboard-friendly controls.','rss-prism');?></p></article></div></section><section class="rp-section rp-container" id="latest"><h2><?php esc_html_e('Latest articles','rss-prism');?></h2><?php $q=new WP_Query(array('post_type'=>'post','post_status'=>'publish','posts_per_page'=>3));if($q->have_posts()):?><div class="entry-grid"><?php while($q->have_posts()):$q->the_post();rss_prism_post_card();endwhile;?></div><?php wp_reset_postdata();else:?><p><?php esc_html_e('Publish a post and it will appear here automatically.','rss-prism');?></p><?php endif;?></section><section class="rp-section rp-container" id="contact"><div class="rp-cta"><h2><?php echo esc_html(get_theme_mod('rss_prism_cta_title','Ready to get started?'));?></h2><p><?php echo esc_html(get_theme_mod('rss_prism_cta_text','Make your next idea real with a website that grows with you.'));?></p><?php $l=get_theme_mod('rss_prism_cta_label','Get in touch');$u=get_theme_mod('rss_prism_cta_url','#contact');if($l&&$u):?><a class="rp-button" href="<?php echo esc_url($u);?>"><?php echo esc_html($l);?> →</a><?php endif;?></div></section><?php while(have_posts()):the_post();if(trim(get_the_content())):?><section class="rp-section rp-container entry-content"><?php the_content();?></section><?php endif;endwhile;?></main><?php get_footer();?>